  },
};

function isNonEmptyText(value) {
  return typeof value === 'string' && value.length > 0;
}

export function normalizeEvent(event) {
  if (event === null || typeof event !== 'object') {
    throw new TypeError('Event must be an object');
  }

  const mapping = EVENT_TYPES[event.type];
  if (mapping === undefined) {
    throw new TypeError(`Unknown event type: ${String(event.type)}`);
  }

  const { data } = event;
  if (data === null || typeof data !== 'object') {
    throw new TypeError(`Incomplete event: ${event.type}`);
  }

  const id = data[mapping.id];
  const occurredAt = data[mapping.occurredAt];
  const actor = data[mapping.actor];

  if (![id, occurredAt, actor].every(isNonEmptyText)) {
    throw new TypeError(`Incomplete event: ${event.type}`);
  }

  return {
    id,
    kind: mapping.kind,
    occurredAt,
    actor,
    summary: `${mapping.label}: ${id}`,
  };
}
